using DocumentFormat.OpenXml.Spreadsheet; using SimpleExcel.Options;
namespace SimpleExcel.Internal;
internal sealed class StyleRegistry
{
 private readonly ExcelWriteOptions _options; private readonly Dictionary<(string Format,bool Wrap),uint> _styles=new(); private readonly List<NumberingFormat> _numberFormats=[]; private readonly List<CellFormat> _cellFormats=[]; private uint _nextFormatId=164;
 public StyleRegistry(ExcelWriteOptions options){_options=options;_cellFormats.Add(new CellFormat());_cellFormats.Add(new CellFormat());_cellFormats.Add(new CellFormat{Alignment=new Alignment{WrapText=true},ApplyAlignment=true});}
 public uint GetStyle(string? format,bool wrap){if(string.IsNullOrWhiteSpace(format))return wrap?2U:0U;var key=(format,wrap);if(_styles.TryGetValue(key,out var id))return id;var numId=_nextFormatId++;_numberFormats.Add(new NumberingFormat{NumberFormatId=numId,FormatCode=format});var cf=new CellFormat{NumberFormatId=numId,ApplyNumberFormat=true};if(wrap){cf.Alignment=new Alignment{WrapText=true};cf.ApplyAlignment=true;}_cellFormats.Add(cf);id=(uint)_cellFormats.Count-1;_styles[key]=id;return id;}
 public Stylesheet Build(){var fonts=new Fonts(new Font(),new Font(_options.Header.Bold?new Bold():null)){Count=2U};var fills=new Fills(new Fill(new PatternFill{PatternType=PatternValues.None}),new Fill(new PatternFill{PatternType=PatternValues.Gray125}));uint fillId=0;if(!string.IsNullOrWhiteSpace(_options.Header.BackgroundColor)){var rgb=NormalizeColor(_options.Header.BackgroundColor);fills.Append(new Fill(new PatternFill(new ForegroundColor{Rgb=rgb},new BackgroundColor{Indexed=64U}){PatternType=PatternValues.Solid}));fillId=2;}fills.Count=(uint)fills.ChildElements.Count;var borders=new Borders(new Border()){Count=1U};_cellFormats[1]=new CellFormat{FontId=1U,FillId=fillId,BorderId=0U,ApplyFont=true,ApplyFill=fillId>0};var cfs=new CellFormats(_cellFormats){Count=(uint)_cellFormats.Count};var ss=new Stylesheet();if(_numberFormats.Count>0)ss.Append(new NumberingFormats(_numberFormats){Count=(uint)_numberFormats.Count});ss.Append(fonts,fills,borders,cfs);return ss;}
 private static string NormalizeColor(string value){var c=value.Trim().TrimStart('#');if(c.Length==6)c="FF"+c;if(c.Length!=8||!c.All(Uri.IsHexDigit))throw new ArgumentException("BackgroundColor debe usar #RRGGBB o AARRGGBB.");return c.ToUpperInvariant();}
}
